export function measure(cells: string[][]): number[] {
  const widths: number[] = [];
  for (const row of cells) {
    row.forEach((cell, i) => {
      // Display width, not length: emoji and CJK take two columns.
      widths[i] = Math.max(widths[i] ?? 0, stringWidth(cell));
